	private BindingMask names(int payloadId) {
		BindingMask result = BindingMask.EMPTY;
		for (int ordinal = 0; payloadId != 0 && ordinal < payloads.childCount(payloadId); ordinal++) {
			int symbol = symbols.symbolId(payloads.childGroupId(payloadId, ordinal));
			if (symbol != 0) {
				result = result.union(BindingMask.single(symbol));
			}
		}
		return result;
	}

	private boolean sameGraphDomain(int first, int second) {
		return relations.graphDomainId(first) == relations.graphDomainId(second)
				&& metadata.relationGraphDomain(first).equals(metadata.relationGraphDomain(second));
	}

	private int intermediate(int source, int operator, int left, int right) {
		binary[0] = relations.groupId(left);
		binary[1] = relations.groupId(right);
		int before = relations.size();
		int result = relations.internCanonical(operator, 0, 0, 0, 0, relations.graphDomainId(source), binary, 0, 2);
		if (result > before) {
			metadata.attachRelation(result, 0, 0, Double.NaN, Double.NaN, 0);
			metadata.attachRelationGraphDomain(result, metadata.relationGraphDomain(source));
			metadata.attachRelationInputContract(result, 0, 0, 0, 0, 0);
			metadata.attachRelationReplaySafety(result, true);
		}
		return result;
	}

	private void addAlternative(int source, int left, int right, long proof) {
		binary[0] = relations.groupId(left);
		binary[1] = relations.groupId(right);
		if (binary[0] == relations.childGroupId(source, 0) && binary[1] == relations.childGroupId(source, 1)) {
			return;
		}
		int alternative = sink.addAlternative(source, PackedRelOp.LEFT_JOIN, 0, binary, 2);
		if (alternative != 0 && alternative != source) {
			sink.addRuleMask(alternative, proof);
		}
	}

	private final class BgpGraphProof {
		private final PlanningGraphDomain domain;
		private int patternCount;
		private int scope;
		private int graphValue;

		private BgpGraphProof(PlanningGraphDomain domain) {
			this.domain = domain;
		}

		private boolean accept(int patternPayload) {
			int patternScope = payloads.payloadId(patternPayload);
			int context = payloads.childGroupId(patternPayload, 3);
			int selectedGraph = 0;
			if (context != 0) {
				if ((payloads.executionDomainId(context) & PackedQuery.TERM_CONSTANT) == 0
						|| payloads.semanticScopeId(context) == 0) {
					return false;
				}
				selectedGraph = payloads.semanticScopeId(context);
			}
			if (domain.kind() == PlanningGraphDomain.Kind.ACTIVE) {
				if (!domain.selector().constant() || !(domain.selector().value() instanceof Resource)) {
					return false;
				}
				// A constant active GRAPH chooses exactly one context for DEFAULT_CONTEXTS patterns.
				if (patternScope == 1) {
					selectedGraph = -1;
				}
			} else if (domain.kind() != PlanningGraphDomain.Kind.DEFAULT) {
				return false;
			}
			if (selectedGraph == 0 || scope != 0 && (scope != patternScope || graphValue != selectedGraph)) {
				return false;
			}
			scope = patternScope;
			graphValue = selectedGraph;
			return true;
		}
	}
